// ======================================================================
// DETERMINISTIC PII SANITIZATION & METADATA EXTRACTION NODE
// Strips HTML, Redacts PII (Credit Cards, Phone Numbers, Emails),
// and Extracts Structured Entities (Order IDs, Tracking Numbers)
// ======================================================================
const items = $input.all();
const results = [];

for (const item of items) {
  const payload = item.json.body || item.json;
  const rawSubject = payload.subject || '';
  const rawBody = payload.body || payload.body_html || payload.message || '';
  const rawEmail = payload.customer_email || payload.email || 'customer@example.com';
  const customerTier = payload.customer_tier || 'Standard';
  const channel = payload.channel || 'email';
  const ticketId = payload.ticket_id || ('TICK-' + Date.now().toString().slice(-6));

  // 1. Strip HTML tags & decode basic entities
  let cleanSubject = rawSubject.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').replace(/\s+([,.!?;:])/g, '$1').trim();
  let cleanBody = rawBody.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').replace(/\s+([,.!?;:])/g, '$1').trim();

  // 2. Strict PII Redaction
  // Credit Card regex (15-16 digits with spaces or hyphens)
  const ccRegex = /\b(?:4[0-9]{12}(?:[0-9]{3})?|5[1-5][0-9]{14}|3[47][0-9]{13}|3(?:0[0-5]|[68][0-9])[0-9]{11}|6(?:011|5[0-9]{2})[0-9]{12}|(?:2131|1800|35\d{3})\d{11}|(?:\d{4}[ -]?){3}\d{4})\b/g;
  cleanBody = cleanBody.replace(ccRegex, '[REDACTED_CC]');
  cleanSubject = cleanSubject.replace(ccRegex, '[REDACTED_CC]');

  // Phone Number regex (domestic & international formats)
  const phoneRegex = /\b(?:\+?\d{1,3}[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}\b/g;
  cleanBody = cleanBody.replace(phoneRegex, '[REDACTED_PHONE]');
  cleanSubject = cleanSubject.replace(phoneRegex, '[REDACTED_PHONE]');

  // Email masking in body
  const emailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,7}\b/g;
  cleanBody = cleanBody.replace(emailRegex, '[REDACTED_EMAIL]');

  // Mask customer email for audit compliance (e.g., j***n@example.com)
  let maskedEmail = '[MASKED_EMAIL]';
  if (rawEmail.includes('@')) {
    const [local, domain] = rawEmail.split('@');
    maskedEmail = local[0] + '***' + (local.length > 1 ? local[local.length - 1] : '') + '@' + domain;
  }

  // 3. Entity Extraction
  // Order IDs (#1000 - #999999 or ORD-XXXXX)
  const orderMatches = (rawSubject + ' ' + rawBody).match(/#\d{4,7}|ORD-[A-Za-z0-9]+/gi) || [];
  const extractedOrderIds = Array.from(new Set(orderMatches.map(o => o.toUpperCase())));

  // Courier Tracking Numbers
  const trackingMatches = (rawSubject + ' ' + rawBody).match(/\b(1Z[0-9A-Z]{16}|\d{12,15}|9\d{21})\b/gi) || [];
  const extractedTracking = Array.from(new Set(trackingMatches));

  const fullText = cleanSubject + ' - ' + cleanBody;

  results.push({
    json: {
      ticket_id: ticketId,
      customer_tier: customerTier,
      channel: channel,
      customer_email_masked: maskedEmail,
      sanitized_subject: cleanSubject,
      sanitized_body: cleanBody,
      text: fullText,
      extracted_order_ids: extractedOrderIds,
      extracted_tracking_numbers: extractedTracking,
      ingested_at: new Date().toISOString()
    }
  });
}

return results;
